func transfer(ctx context.Context, db *sql.DB, from, to int64, amount int64) (err error) {
    tx, err := db.BeginTx(ctx, nil)
    if err != nil { return err }
    defer tx.Rollback()

    if _, err = tx.ExecContext(ctx, debitSQL, amount, from); err != nil { return err }
    if _, err = tx.ExecContext(ctx, creditSQL, amount, to); err != nil { return err }
    return tx.Commit()
}
